#!/bin/bash
# Pre-commit hook: auto-assemble CLAUDE.md if sources changed.
# CLAUDE.md is gitignored (generated file), but Claude reads it every session.
# Keeps it fresh so the next tool call or session sees current conventions.
# Called from .hooks/pre-commit (generated by init-devshop.sh, invoked by husky).
set -euo pipefail

DEVSHOP_CLAUDE="/devshop/CLAUDE.md"
PROJECT_CLAUDE="CLAUDE.project.md"
ASSEMBLED="CLAUDE.md"

# Skip if devshop source doesn't exist (not in a devshop-managed project)
[ -f "$DEVSHOP_CLAUDE" ] || exit 0

# Build expected content the same way init-devshop.sh does:
# cp devshop CLAUDE.md, then append newline + project CLAUDE.project.md
EXPECTED_FILE=$(mktemp)
cp "$DEVSHOP_CLAUDE" "$EXPECTED_FILE"
if [ -f "$PROJECT_CLAUDE" ]; then
  printf '\n' >> "$EXPECTED_FILE"
  cat "$PROJECT_CLAUDE" >> "$EXPECTED_FILE"
fi

# Compare with current assembled file
if [ -f "$ASSEMBLED" ] && diff -q "$EXPECTED_FILE" "$ASSEMBLED" >/dev/null 2>&1; then
  rm "$EXPECTED_FILE"
  exit 0
fi

# Stale — reassemble (gitignored, no staging needed)
mv "$EXPECTED_FILE" "$ASSEMBLED"
echo "✓ CLAUDE.md reassembled from sources."
